#!/usr/bin/env bash
# ============================================================================
# agent-cost-bench — quickstart.sh
#
# Runs a minimal 2-task benchmark using the config generated by setup.sh.
# This is a low-cost validation run (~$0.30–0.60 total) to confirm everything
# works before committing to a full 14-task run.
#
# Usage:
#   ./quickstart.sh                    # Uses config.generated.yaml
#   ./quickstart.sh my-config.yaml     # Uses a custom config
# ============================================================================

set -euo pipefail

# Colors
RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
BLUE='\033[0;34m'
NC='\033[0m'

info()  { echo -e "${BLUE}▸${NC} $*"; }
ok()    { echo -e "${GREEN}✓${NC} $*"; }
warn()  { echo -e "${YELLOW}⚠${NC} $*"; }
fail()  { echo -e "${RED}✗${NC} $*"; }

echo ""
echo -e "${BLUE}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
echo -e "${BLUE}  agent-cost-bench — Quickstart${NC}"
echo -e "${BLUE}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
echo ""

# ---------------------------------------------------------------------------
# Check prerequisites
# ---------------------------------------------------------------------------

# Activate venv if not already active
if [[ -z "${VIRTUAL_ENV:-}" && -f ".venv/bin/activate" ]]; then
    # shellcheck disable=SC1091
    source .venv/bin/activate
fi

if ! command -v agent-cost-bench &>/dev/null; then
    fail "agent-cost-bench not found. Run ./setup.sh first."
    exit 1
fi

# ---------------------------------------------------------------------------
# Determine config
# ---------------------------------------------------------------------------

CONFIG="${1:-config.generated.yaml}"

if [[ ! -f "$CONFIG" ]]; then
    fail "Config file not found: $CONFIG"
    echo "  Run ./setup.sh first to generate a config, or specify one:"
    echo "  ./quickstart.sh path/to/config.yaml"
    exit 1
fi

ok "Using config: $CONFIG"

# Count runners
RUNNER_COUNT=$(grep -c "^  - name:" "$CONFIG" 2>/dev/null || echo "0")
info "Runners: $RUNNER_COUNT CLIs detected in config"

# ---------------------------------------------------------------------------
# Create quickstart config (2 tasks only)
# ---------------------------------------------------------------------------

QUICK_CONFIG="/tmp/agent-cost-bench-quickstart.yaml"

# Copy the config but override task_ids to just 2 quick tasks
# and set a distinct workspace + report title
python3 -c "
import yaml, sys

with open('$CONFIG') as f:
    cfg = yaml.safe_load(f)

cfg['task_ids'] = ['rest-api', 'terraform-s3']
cfg['workspace_base'] = '/tmp/agent-cost-bench-quickstart'
cfg['report_title'] = 'Quickstart: ' + cfg.get('report_title', 'Benchmark')
cfg['open_report'] = True

with open('$QUICK_CONFIG', 'w') as f:
    yaml.dump(cfg, f, default_flow_style=False, sort_keys=False)
"

ok "Quickstart config: 2 tasks (rest-api, terraform-s3) × $RUNNER_COUNT CLIs"

# ---------------------------------------------------------------------------
# Estimate cost
# ---------------------------------------------------------------------------

echo ""
info "Estimated cost for this quickstart run:"
echo ""
echo "    Task          Kiro        Claude Code   Copilot     Cursor"
echo "    rest-api      ~\$0.03–0.05  ~\$0.20–0.30  ~\$0.15–0.20  ~\$0.20–0.35"
echo "    terraform-s3  ~\$0.02–0.03  ~\$0.15–0.22  ~\$0.10–0.14  ~\$0.07–0.10"
echo ""
echo "    Total (${RUNNER_COUNT} CLIs × 2 tasks): ~\$0.30–1.20"
echo ""

read -r -p "  Proceed? [Y/n]: " PROCEED
if [[ "${PROCEED:-y}" =~ ^[Nn] ]]; then
    echo "  Cancelled. Run manually with: agent-cost-bench cli-compare run $CONFIG"
    exit 0
fi

# ---------------------------------------------------------------------------
# Run the benchmark
# ---------------------------------------------------------------------------

echo ""
info "Starting quickstart benchmark..."
echo "  This typically takes 2–5 minutes."
echo ""

START_TIME=$(date +%s)

agent-cost-bench cli-compare run "$QUICK_CONFIG"

END_TIME=$(date +%s)
ELAPSED=$((END_TIME - START_TIME))
MINUTES=$((ELAPSED / 60))
SECONDS=$((ELAPSED % 60))

# ---------------------------------------------------------------------------
# Summary
# ---------------------------------------------------------------------------

echo ""
echo -e "${GREEN}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
echo -e "${GREEN}  Quickstart complete! (${MINUTES}m ${SECONDS}s)${NC}"
echo -e "${GREEN}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
echo ""
echo "  Reports are in: results/"
echo ""

# Find the latest report
LATEST_REPORT=$(ls -t results/*.html 2>/dev/null | head -1)
if [[ -n "${LATEST_REPORT:-}" ]]; then
    echo "  Latest report: $LATEST_REPORT"
    echo ""
    echo "  Open it with:"
    echo "    open $LATEST_REPORT        # macOS"
    echo "    xdg-open $LATEST_REPORT    # Linux"
fi

echo ""
echo "  Ready for a full run?"
echo "    agent-cost-bench cli-compare run $CONFIG"
echo ""
